export const css = ".tb-menu{position:relative;pointer-events:auto}.tb-menu summary{list-style:none;display:flex;align-items:center;gap:12px;height:44px;padding:0 4px;cursor:pointer;color:var(--tabit-ink,#FBF9F4);font-size:13px;font-weight:500;letter-spacing:.02em;user-select:none}.tb-menu summary::-webkit-details-marker{display:none}.tb-menu summary:focus-visible{outline:2px solid #A8823A;outline-offset:3px}.tb-menu-ic{display:block;width:22px;height:12px;position:relative}.tb-menu-ic i{position:absolute;left:0;right:0;height:1.5px;background:var(--tabit-ink,#FBF9F4);transition:transform .25s cubic-bezier(.23,1,.32,1),top .25s cubic-bezier(.23,1,.32,1)}.tb-menu-ic i:first-child{top:0}.tb-menu-ic i:last-child{top:10.5px}.tb-menu[open] .tb-menu-ic i:first-child{top:5.25px;transform:rotate(45deg)}.tb-menu[open] .tb-menu-ic i:last-child{top:5.25px;transform:rotate(-45deg)}.tb-menu-nav{position:absolute;left:-16px;top:60px;width:280px;padding:10px 28px 12px;background:rgba(8,13,30,.94);-webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px);border:1px solid rgba(184,192,212,.14);border-radius:2px;display:flex;flex-direction:column;z-index:12}.tb-menu-nav a{display:block;padding:12px 0;font-size:17px;line-height:24px;font-weight:400;letter-spacing:-.01em;color:var(--tb-text,#FBF9F4);text-decoration:none;border-top:1px solid rgba(246,242,234,.12);transition:color .25s ease}.tb-menu-nav a:first-child{border-top:0}.tb-menu-nav a:hover{color:var(--tb-gold,#A8823A)}.tb-menu-nav a[aria-current=\"page\"]{color:var(--tb-gold,#A8823A)}@media (prefers-reduced-motion: reduce){.tb-menu-ic i{transition:none}}\n\n.tb-page a{color:#FBF9F4}.tb-page a:hover{color:#A8823A}\n.tb-sky{background-color:#04070F}\n@media (max-width: 760px){.tb-why{grid-template-columns:1fr!important;grid-auto-rows:auto!important}}\n.tb-cells{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));grid-auto-rows:1fr;gap:16px}\n.tb-da{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:40px 56px}\n@media (max-width: 1100px){.tb-cells{grid-template-columns:repeat(2,minmax(0,1fr))}}\n@media (max-width: 760px){.tb-cells,.tb-da{grid-template-columns:1fr;grid-auto-rows:auto}}\n.tb-btn:hover{filter:brightness(1.08);color:#04070F}\n";
